     * in force for each grade that has its own. And every value recorded for the settings that carry
     * a figure, by key and from-date.
     */
    public record SettingsResponse(String clerkLimit, String floor, int terms, String latePct, String policyDate,
            String periodNumberingFrom, Map<String, Integer> gradeTerms, String cap, List<DatedValue> dated) {
    }

    private static SettingsResponse response(Sheet sheet) {
        return new SettingsResponse(SettingService.text(sheet.getClerkLimit()), SettingService.text(sheet.getFloor()),
                sheet.getTerms(), SettingService.text(sheet.getLatePct()),
                sheet.getPolicyDate() == null ? "" : sheet.getPolicyDate().toString(),
                sheet.getPeriodNumberingFrom() == null ? "" : sheet.getPeriodNumberingFrom().toString(),
                sheet.getGradeTerms(), SettingService.text(sheet.getCap()),
                sheet.getSettings().stream().map(SettingController::dated).toList());
    }

    private static DatedValue dated(DatedSetting s) {
        String value = s.getValue() == null ? ""
                : s.getKey().startsWith(SettingService.TERMS) ? String.valueOf(s.getValue().intValue())
                : SettingService.text(s.getValue());
        return new DatedValue(s.getKey(), s.getFromDate() == null ? "" : s.getFromDate().toString(), value);
    }

    private final SettingService service;

    public SettingController(SettingService service) {
        this.service = service;
    }

    @PostMapping("/get")
    public SettingsResponse get(@Valid @RequestBody GetSettingsRequest req) {
        return response(service.get(req.sheet().trim(), req.user().trim()));
    }

    @PostMapping("/set")
    public SettingsResponse set(@Valid @RequestBody SetSettingsRequest req) {
        String policy = req.policyDate() == null ? "" : req.policyDate().trim();
        String numberingFrom = req.periodNumberingFrom() == null ? "" : req.periodNumberingFrom().trim();
        Map<String, SettingService.Dated<Integer>> gradeTerms = new TreeMap<>();
        if (req.termsA() != null) gradeTerms.put("A", terms(req.termsA(), req.termsAFrom()));
        if (req.termsB() != null) gradeTerms.put("B", terms(req.termsB(), req.termsBFrom()));
        if (req.termsC() != null) gradeTerms.put("C", terms(req.termsC(), req.termsCFrom()));
        return response(service.set(req.sheet().trim(), req.user().trim(),
                req.clerkLimit() == null ? null : amount(req.clerkLimit(), req.clerkLimitFrom()),
                req.floor() == null ? null : amount(req.floor(), req.floorFrom()),
                req.terms() == null ? null : terms(req.terms(), req.termsFrom()),
                req.latePct() == null ? null : amount(req.latePct(), req.latePctFrom()), req.policyDate() != null,
                policy.isEmpty() ? null : date(policy), req.periodNumberingFrom() != null,
                numberingFrom.isEmpty() ? null : date(numberingFrom),
                req.cap() == null ? null : amount(req.cap(), req.capFrom()), gradeTerms));
    }

    /** An amount (blank: none) from a from-date (blank or null: the sheet's today). */
    private static SettingService.Dated<BigDecimal> amount(String value, String from) {
        String text = value.trim();
        return new SettingService.Dated<>(text.isEmpty() ? null : ClaimController.amount(text), from(from));
    }

    /** Terms from a from-date (blank or null: the sheet's today). */
    private static SettingService.Dated<Integer> terms(String value, String from) {
        return new SettingService.Dated<>(Integer.valueOf(value.trim()), from(from));
    }

    private static LocalDate from(String text) {
        return text == null || text.isBlank() ? null : date(text.trim());
    }

    private static LocalDate date(String text) {
        try {
            return LocalDate.parse(text);
        } catch (DateTimeParseException e) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Not a date: " + text + ".");
        }
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.Map;
import java.util.TreeMap;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Rounding;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The sheet's settings: its clerk limit (none: no limit) and its floor, the least a claim's live due
 * can be, and its terms, the days after its date a claim is due by, and its late percent, what an
 * overdue claim gains of its figure for every full 30 days overdue. Changing the floor or the late
 * percent moves the figures, so the figures that move are recorded. Its policy date (none:
 * the sheet's today) decides how a claim's live figures round (see {@link Rounding}), so changing it
 * records the figures that move too. Its period-numbering-from date (none: off) decides how a claim
 * opened is numbered: on or after it, within its period (see {@link SheetService#nextClaimNumber}).
 * Its cap (none: no cap) is the most a person's due-total can be, so changing it records the
 * figures that move too. A grade may have its own terms; a grade without uses the sheet's terms. A claim's due-by is fixed
 * when it is created, so changing any terms moves no claim's due-by.
 * <p>
 * The settings that carry a figure (the floor, the late percent, the terms, a grade's own terms,
 * the clerk limit and the cap) are dated: each value is recorded from a from-date (the sheet's
 * today when none is given). A claim's floor, late percent and terms are those in force on its
 * date; the clerk limit and the cap are those in force on the sheet's today (see {@link Sheet}).
 * The policy date and the period-numbering-from date are not dated.
 */
@Service
public class SettingService {

    public static final String CLERK_LIMIT = Sheet.CLERK_LIMIT;
    public static final String FLOOR = Sheet.FLOOR;
    public static final String CAP = Sheet.CAP;
    public static final String TERMS = Sheet.TERMS;
    /** The key of a grade's own terms: {@code terms-<grade>}. */
    public static final String GRADE_TERMS = Sheet.GRADE_TERMS;
    public static final String LATE_PCT = Sheet.LATE_PCT;
    public static final String POLICY_DATE = "policy-date";
    public static final String PERIOD_NUMBERING_FROM = "period-numbering-from";

    private final SheetService sheets;
    private final SheetRepository sheetStore;
    private final RollupService rollup;
    private final Audit audit;

    public SettingService(SheetService sheets, SheetRepository sheetStore, RollupService rollup, Audit audit) {
        this.sheets = sheets;
        this.sheetStore = sheetStore;
        this.rollup = rollup;
        this.audit = audit;
    }

    @Transactional
    public Sheet get(String sheetId, String user) {
        return sheets.load(sheetId, user);
    }

    /**
     * A value to record for a setting that carries a figure (null for none: no limit, no cap) from
     * a from-date (null: from the sheet's today, and the record names no from-date).
     */
    public record Dated<T>(T value, LocalDate from) {
    }

    /**
     * Save the settings given: a clerk limit when {@code limit} is not null, and the floor, the
     * terms and the late percent when they are not null, and a policy date when {@code changePolicy}
     * (null for none), and a period-numbering-from date when {@code changeNumbering} (null for off),
     * and a cap when {@code cap} is not null, and each grade's own terms given in {@code gradeTerms}
     * (by grade, in grade order). Each figure is recorded from its from-date, keeping the values
     * already recorded (one already recorded from that date is replaced). Each one saved is
     * recorded, in that order.
     */
    @Transactional
    public Sheet set(String sheetId, String user, Dated<BigDecimal> limit, Dated<BigDecimal> floor,
            Dated<Integer> terms, Dated<BigDecimal> latePct, boolean changePolicy, LocalDate policyDate,
            boolean changeNumbering, LocalDate numberingFrom, Dated<BigDecimal> cap,
            Map<String, Dated<Integer>> gradeTerms) {
        Sheet sheet = sheets.load(sheetId, user);
        if (limit != null) {
            sheet = record(sheet, user, CLERK_LIMIT, limit.value(), limit.from(), text(limit.value()), false);
        }
        if (floor != null) {
            sheet = record(sheet, user, FLOOR, floor.value(), floor.from(), text(floor.value()), true);
        }
        if (terms != null) {
            sheet = record(sheet, user, TERMS, BigDecimal.valueOf(terms.value()), terms.from(),
                    String.valueOf(terms.value()), false);
        }
        if (latePct != null) {
            sheet = record(sheet, user, LATE_PCT, latePct.value(), latePct.from(), text(latePct.value()), true);
        }
        if (changePolicy) {
            RollupService.Snapshot before = rollup.snapshot(sheetId);
            sheet.setPolicyDate(policyDate);
            sheet = sheetStore.saveAndFlush(sheet);
            audit.recordOnCommit(changed(sheetId, user, POLICY_DATE, policyDate == null ? "" : policyDate.toString()));
            rollup.recordChanges(sheetId, user, before);
        }
        if (changeNumbering) {
            sheet.setPeriodNumberingFrom(numberingFrom);
            sheet = sheetStore.saveAndFlush(sheet);
            audit.recordOnCommit(changed(sheetId, user, PERIOD_NUMBERING_FROM,
                    numberingFrom == null ? "" : numberingFrom.toString()));
        }
        if (cap != null) {
            sheet = record(sheet, user, CAP, cap.value(), cap.from(), text(cap.value()), true);
        }
        for (Map.Entry<String, Dated<Integer>> e : new TreeMap<>(gradeTerms).entrySet()) {
            Dated<Integer> t = e.getValue();
            sheet = record(sheet, user, GRADE_TERMS + e.getKey(), BigDecimal.valueOf(t.value()), t.from(),
                    String.valueOf(t.value()), false);
        }
        return sheet;
    }

    /**
     * Record a setting's value from a from-date (null: the sheet's today) and audit it; when it
     * {@code moves} the figures, the figures that move are recorded too.
     */
    private Sheet record(Sheet sheet, String user, String key, BigDecimal value, LocalDate from, String text,
            boolean moves) {
        String sheetId = sheet.getId();
        RollupService.Snapshot before = moves ? rollup.snapshot(sheetId) : null;
        sheet.record(key, from != null ? from : sheet.getToday(), value);
        Sheet saved = sheetStore.saveAndFlush(sheet);
        audit.recordOnCommit(changed(sheetId, user, key, text) + (from != null ? " from=" + from : ""));
        if (moves) {
            rollup.recordChanges(sheetId, user, before);
        }
        return saved;
    }

    private static String changed(String sheetId, String user, String key, String value) {
        return "SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=" + key + " value=" + value;
    }

    /** A limit with two decimals, or blank for none. */
    public static String text(BigDecimal limit) {
        return limit == null ? "" : limit.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
    }
}

package net.officefloor.hq.app.sheet;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.Instant;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.TreeMap;

/** A sheet: the unit everything else in the app is kept under. Created on its first load. */
@Entity
@Table(name = "sheet")
public class Sheet {

    /** The floor a sheet starts with. */
    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");

    /** The terms a sheet starts with, in days. */
    public static final int DEFAULT_TERMS = 14;

    /** The late percent a sheet starts with. */
    public static final BigDecimal DEFAULT_LATE_PCT = new BigDecimal("0.00");

    public static final String CLERK_LIMIT = "clerk-limit";
    public static final String FLOOR = "floor";
    public static final String CAP = "cap";
    public static final String TERMS = "terms";
    /** The key of a grade's own terms: {@code terms-<grade>}. */
    public static final String GRADE_TERMS = "terms-";
    public static final String LATE_PCT = "late-pct";

    @Id
    private String id;

    @Column(name = "created_by", nullable = false)
    private String createdBy;

    @Column(name = "created_at", nullable = false)
    private Instant createdAt;

    /** The sheet's today: every date-dependent decision and default date uses it, never the clock. */
    @Column(name = "today", nullable = false)
    private LocalDate today;

    /** The last claim number given on the sheet; the next claim opened takes the one after. */
    @Column(name = "last_claim_number", nullable = false)
    private int lastClaimNumber;

    /**
     * The values recorded for the settings that carry a figure (the floor, the late percent, the
     * terms, a grade's own terms, the clerk limit and the cap), each from a from-date.
     */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "sheet_setting", joinColumns = @JoinColumn(name = "sheet_id"))
    private List<DatedSetting> settings = new ArrayList<>();

    /** The date a claim's rounding turns on: half up before it, half to even on or after; null for the sheet's today. */
    @Column(name = "policy_date")
    private LocalDate policyDate;

    /** The date numbering per period starts: on or after it a claim opened is numbered within its period; null for off. */
    @Column(name = "period_numbering_from")
    private LocalDate periodNumberingFrom;

    /** The last number given in the sheet's X sequence, to claims opened under numbering per period in no period. */
    @Column(name = "last_unperiod_claim_number", nullable = false)
    private int lastUnperiodClaimNumber;

    protected Sheet() {
    }

    public Sheet(String id, String createdBy, Instant createdAt, LocalDate today) {
        this.id = id;
        this.createdBy = createdBy;
        this.createdAt = createdAt;
        this.today = today;
    }

    public String getId() {
        return id;
    }

    public String getCreatedBy() {
        return createdBy;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public LocalDate getToday() {
        return today;
    }

    public void setToday(LocalDate today) {
        this.today = today;
    }

    /**
     * Record a setting's value from a from-date, keeping the values already recorded; a value
     * already recorded for the key from that date is replaced. A null value is none.
     */
    public void record(String key, LocalDate fromDate, BigDecimal value) {
        settings.removeIf(s -> s.getKey().equals(key) && Objects.equals(s.getFromDate(), fromDate));
        settings.add(new DatedSetting(key, fromDate, value));
    }

    /** The values recorded for the settings, by key and then by from-date (from the beginning of time first). */
    public List<DatedSetting> getSettings() {
        return settings.stream().sorted(Comparator.comparing(DatedSetting::getKey).thenComparing(
                DatedSetting::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder()))).toList();
    }

    /**
     * The value of a setting recorded with the latest from-date on or before the date (one from the
     * beginning of time counting as the earliest); empty when none is recorded by then.
     */
    private Optional<DatedSetting> inForce(String key, LocalDate date) {
        return settings.stream().filter(s -> s.getKey().equals(key))
                .filter(s -> s.getFromDate() == null || date == null || !s.getFromDate().isAfter(date))
                .max(Comparator.comparing(DatedSetting::getFromDate,
                        Comparator.nullsFirst(Comparator.naturalOrder())));
    }

    /** The clerk limit in force on the sheet's today: the most a clerk may settle a claim's due at; null for no limit. */
    public BigDecimal getClerkLimit() {
        return inForce(CLERK_LIMIT, today).map(DatedSetting::getValue).orElse(null);
    }

    /** The floor in force on the sheet's today. */
    public BigDecimal getFloor() {
        return floorOn(today);
    }

    /** The floor in force on a date: the least the live due of a claim of that date can be. */
    public BigDecimal floorOn(LocalDate date) {
        return inForce(FLOOR, date).map(DatedSetting::getValue).orElse(DEFAULT_FLOOR);
    }

    /** The cap in force on the sheet's today: the most a person's due-total can be; null for no cap. */
    public BigDecimal getCap() {
        return inForce(CAP, today).map(DatedSetting::getValue).orElse(null);
    }

    /** A person's due-total held to the cap in force on the sheet's today (n/a stays n/a). */
    public BigDecimal capped(BigDecimal dueTotal) {
        BigDecimal cap = getCap();
        return dueTotal == null || cap == null ? dueTotal : dueTotal.min(cap);
    }

    /** The sheet's terms in force on the sheet's today. */
    public int getTerms() {
        return termsOn(today);
    }

    /** The sheet's terms in force on a date. */
    private int termsOn(LocalDate date) {
        return inForce(TERMS, date).map(s -> s.getValue().intValue()).orElse(DEFAULT_TERMS);
    }

    /** The terms in force on the sheet's today for each grade that has its own then, by grade. */
    public Map<String, Integer> getGradeTerms() {
        Map<String, Integer> terms = new TreeMap<>();
        settings.stream().map(DatedSetting::getKey).filter(k -> k.startsWith(GRADE_TERMS)).distinct()
                .forEach(k -> inForce(k, today).ifPresent(s -> terms.put(k.substring(GRADE_TERMS.length()),
                        s.getValue().intValue())));
        return terms;
    }

    /** The terms for a grade on a date: its own in force then, else the sheet's in force then. */
    public int termsFor(String grade, LocalDate date) {
        return (grade == null ? Optional.<DatedSetting>empty() : inForce(GRADE_TERMS + grade, date))
                .map(s -> s.getValue().intValue()).orElseGet(() -> termsOn(date));
    }

    /** The late percent in force on the sheet's today. */
    public BigDecimal getLatePct() {
        return latePctOn(today);
    }

    /** The late percent in force on a date: what an overdue claim of that date gains of its figure. */
    public BigDecimal latePctOn(LocalDate date) {
        return inForce(LATE_PCT, date).map(DatedSetting::getValue).orElse(DEFAULT_LATE_PCT);
    }

    public LocalDate getPolicyDate() {
        return policyDate;
    }

    public void setPolicyDate(LocalDate policyDate) {
        this.policyDate = policyDate;
    }

    public LocalDate getPeriodNumberingFrom() {
        return periodNumberingFrom;
    }

    public void setPeriodNumberingFrom(LocalDate periodNumberingFrom) {
        this.periodNumberingFrom = periodNumberingFrom;
    }

    /** Whether a claim opened on the sheet's today is numbered within its period. */
    public boolean numbersByPeriod() {
        return periodNumberingFrom != null && !today.isBefore(periodNumberingFrom);
    }

    /** Give out the next number in the sheet's X sequence, for a claim in no period. */
    public int nextUnperiodClaimNumber() {
        return ++lastUnperiodClaimNumber;
    }

    /** Give out the next claim number on the sheet. */
    public int nextClaimNumber() {
        return ++lastClaimNumber;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.PeriodService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * The claims on a sheet: added to a person and edited (amount, date, note). A claim given no date
 * takes the sheet's today. A claim starts as DRAFT and moves through its statuses (see
 * {@link ClaimStatus}); a change its status does not allow is refused. Only a DRAFT can be edited:
 * to change an open claim, void it and add a new one. Settling a claim fixes its
 * due at the rate its person's grade has then for the claim's date; an open claim's due stays live.
 * A claim records who opened it, and that user cannot settle it (four eyes). A claim bound by its
 * person's last statement keeps the figure it had then, and settling it fixes that figure. No claim
 * dated inside a closed period can be added, edited (to or from such a date) or change status. No
 * claim can be added or edited to a date after its person's retirement date. A clerk settles a claim
 * only when its figure is at or below the sheet's clerk limit (a claim with no figure is within any
 * limit); a clerk settling one above it makes it PENDING instead. A steward settles any claim, and
 * approves a PENDING claim (SETTLED, its due fixed then) or rejects it with a reason (back to OPEN);
 * the user who opened a claim cannot approve it. A PENDING claim is not bound by a statement: it
 * shows its live figure, and is bound again by the last statement once rejected. A claim's live due is never below the sheet's floor. An
 * overdue claim's due gains a late charge on top of its figure (see {@link LateCharge}); a statement
 * binds only the figure under it, and settling fixes the charge into the settled due. A claim with
 * a negative amount is a correction: it is allowed only when it names, by number, a SETTLED claim
 * of the same person that it corrects. Its due has no floor and no late charge. A steward can move
 * a DRAFT, OPEN or PENDING claim to another person: it keeps its number and date, loses any figure
 * a statement bound it to, and is listed as its new person's newest claim. A steward can re-settle
 * a SETTLED claim: its due is fixed again at the figure it would have today as an open claim bound
 * by no statement (today's rates, grades, floor and late charge). An OPEN claim can be deferred to
 * a date after the sheet's today: until the sheet's today reaches it the claim counts in no total,
 * is not overdue, cannot be settled and is left unbound by a statement; from then on it is an OPEN
 * claim like any other.
 */
@Service
public class ClaimService {

    private final ClaimRepository claims;
    private final PersonRepository people;
    private final RateRepository rates;
    private final SheetService sheets;
    private final Audit audit;
    private final RollupService rollup;
    private final PeriodService periods;
    private final RoleService roles;

    public ClaimService(ClaimRepository claims, PersonRepository people, RateRepository rates, SheetService sheets,
            Audit audit, RollupService rollup, PeriodService periods, RoleService roles) {
        this.roles = roles;
        this.rollup = rollup;
        this.periods = periods;
        this.claims = claims;
        this.people = people;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    /**
     * A claim's figure under any late charge: the due fixed when settled, else the one bound by a
     * statement (not while PENDING), else the live due; null when it has none.
     */
    public BigDecimal figure(String sheetId, Person person, Claim claim) {
        if (claim.getStatus() == ClaimStatus.SETTLED) {
            return claim.getSettledDue();
        }
        return claim.isStated() && claim.getStatus() != ClaimStatus.PENDING ? claim.getStatedDue()
                : due(sheetId, person, claim);
    }

    /** A claim's figure with its late charge on the sheet's today added on top; null when it has none. */
    public BigDecimal charged(String sheetId, Person person, Claim claim) {
        return LateCharge.withCharge(sheets.sheet(sheetId), claim, figure(sheetId, person, claim));
    }

    @Transactional(readOnly = true)
    public List<Claim> list(String sheetId) {
        return claims.findBySheetIdOrderByListedDesc(sheetId);
    }

    @Transactional
    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
            String corrects) {
        Person person = person(sheetId, personId);
        LocalDate dated = dateOrToday(sheetId, date);
        periods.refuseIfClosed(sheetId, dated);
        refuseIfRetired(person, dated);
        String corrected = corrected(sheetId, personId, amount, corrects);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Claim claim = new Claim(sheetId, personId, amount, dated,
                dated.plusDays(sheets.sheet(sheetId).termsFor(person.gradeOn(dated), dated)), note, corrected);
        logStatus(sheetId, user, person, claim);
        Claim added = claims.saveAndFlush(claim);
        audit.recordOnCommit(record("CLAIM_ADDED", sheetId, user, person, added));
        rollup.recordChanges(sheetId, user, before);
        return added;
    }

    @Transactional
    public Claim update(String sheetId, String user, long id, BigDecimal amount, LocalDate date, String note,
            String corrects) {
        Claim claim = claims.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be edited.");
        }
        LocalDate dated = dateOrToday(sheetId, date);
        periods.refuseIfClosed(sheetId, claim.getDate());
        periods.refuseIfClosed(sheetId, dated);
        refuseIfRetired(person(sheetId, claim.getPersonId()), dated);
        String corrected = corrected(sheetId, claim.getPersonId(), amount, corrects);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        claim.setAmount(amount);
        claim.setDate(dated);
        claim.setNote(note);
        claim.setCorrects(corrected);
        Claim saved = claims.saveAndFlush(claim);
        audit.recordOnCommit(record("CLAIM_EDITED", sheetId, user, person(sheetId, saved.getPersonId()), saved));
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * Move a claim to a new status, refused (409) when its current status does not allow it, and
     * refused (403) when the user who opened it tries to settle it. A clerk settling one whose
     * figure is above the sheet's clerk limit makes it PENDING instead.
     */
    @Transactional
    public Claim changeStatus(String sheetId, String user, long id, ClaimStatus next) {
        return changeStatus(sheetId, user, id, next, null, false);
    }

    /**
     * Approve a PENDING claim: it becomes SETTLED, its due fixed at its live figure with its late
     * charge on the sheet's today. Refused (409) when not PENDING, and (403) for a clerk or the
     * user who opened it.
     */
    @Transactional
    public Claim approve(String sheetId, String user, long id) {
        return changeStatus(sheetId, user, id, ClaimStatus.SETTLED, null, true);
    }

    /**
     * Reject a PENDING claim with a reason: it is OPEN again, bound again by the last statement if
     * that statement included it. Refused (409) when not PENDING, and (403) for a clerk.
     */
    @Transactional
    public Claim reject(String sheetId, String user, long id, String reason) {
        return changeStatus(sheetId, user, id, ClaimStatus.OPEN, reason, true);
    }

    /** Move a claim to a new status; {@code review} for a steward's approval or rejection of a PENDING claim. */
    private Claim changeStatus(String sheetId, String user, long id, ClaimStatus next, String reason,
            boolean review) {
        // lock the sheet's numbering before reading the claim, so a claim is opened (and numbered) once
        if (next == ClaimStatus.OPEN) {
            sheets.lock(sheetId);
        }
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Claim claim = claims.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
        ClaimStatus was = claim.getStatus();
        // only a steward's review moves a PENDING claim on, other than voiding it
        if (!was.canBecome(next) || (next != ClaimStatus.VOID && review != (was == ClaimStatus.PENDING))) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
        }
        periods.refuseIfClosed(sheetId, claim.getDate());
        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then.");
        }
        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                    "The user who opened a claim cannot " + (review ? "approve" : "settle") + " it.");
        }
        if (review && !isSteward(sheetId, user)) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                    "Only a steward can approve or reject a PENDING claim.");
        }
        Person person = person(sheetId, claim.getPersonId());
        // settling fixes the figure with its late charge as it stands on the sheet's today (a
        // PENDING claim's figure is live)
        BigDecimal settling = next == ClaimStatus.SETTLED ? charged(sheetId, person, claim) : null;
        if (next == ClaimStatus.SETTLED && !review && aboveClerkLimit(sheetId, user, settling)) {
            next = ClaimStatus.PENDING;
            settling = null;
        }
        claim.setStatus(next);
        if (next == ClaimStatus.OPEN && !review) {
            claim.setNumber(sheets.nextClaimNumber(sheetId, claim.getDate()));
            claim.setOpenedBy(user);
        } else if (next == ClaimStatus.SETTLED) {
            claim.setSettledDue(settling);
        }
        logStatus(sheetId, user, person, claim);
        Claim saved = claims.saveAndFlush(claim);
        String event = switch (next) {
            case OPEN -> review ? "CLAIM_REJECTED" : "CLAIM_OPENED";
            case PENDING -> "CLAIM_PENDING";
            case SETTLED -> review ? "CLAIM_APPROVED" : "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DRAFT -> throw new IllegalStateException();
        };
        audit.recordOnCommit(record(event, sheetId, user, person, saved)
                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
                + (next == ClaimStatus.SETTLED ? " due=" + dueText(saved.getSettledDue()) : "")
                + (reason != null ? " reason=" + reason : ""));
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it
     * the claim counts in no total, is not overdue, cannot be settled and is left unbound by a
     * statement (deferring unbinds it). Refused (409) for a claim that is not OPEN, (400) for a date
     * not after the sheet's today and (423) when dated inside a closed period.
     */
    @Transactional
    public Claim defer(String sheetId, String user, long id, LocalDate until) {
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Claim claim = claims.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
        if (claim.getStatus() != ClaimStatus.OPEN) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be deferred.");
        }
        if (!until.isAfter(sheets.today(sheetId))) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
                    "A claim can only be deferred to a date after the sheet's today.");
        }
        periods.refuseIfClosed(sheetId, claim.getDate());
        Person person = person(sheetId, claim.getPersonId());
        claim.setDeferredUntil(until);
        claim.bind(false, null);
        Claim saved = claims.saveAndFlush(claim);
        audit.recordOnCommit(record("CLAIM_DEFERRED", sheetId, user, person, saved)
                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "") + " until=" + until);
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * Re-settle a SETTLED claim: fix its due again at the figure it would have on the sheet's today
     * as an open claim bound by no statement, with its late charge. Refused (403) for anyone but a
     * steward, (409) for a claim that is not SETTLED and (423) when dated inside a closed period.
     */
    @Transactional
    public Claim resettle(String sheetId, String user, long id) {
        if (!isSteward(sheetId, user)) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can re-settle a claim.");
        }
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Claim claim = claims.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
        if (claim.getStatus() != ClaimStatus.SETTLED) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be re-settled.");
        }
        periods.refuseIfClosed(sheetId, claim.getDate());
        Person person = person(sheetId, claim.getPersonId());
        BigDecimal old = claim.getSettledDue();
        BigDecimal settling = LateCharge.withChargeAsOpen(sheets.sheet(sheetId), claim, due(sheetId, person, claim));
        claim.setSettledDue(settling);
        logStatus(sheetId, user, person, claim);
        Claim saved = claims.saveAndFlush(claim);
        audit.recordOnCommit(record("CLAIM_RESETTLED", sheetId, user, person, saved)
                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
                + " old=" + dueText(old) + " new=" + dueText(settling));
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * Move a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its number and
     * date, is unbound from any statement (live again until its new person's next statement), and
     * is listed first under its new person. Refused (403) for a clerk, (409) for a SETTLED or VOID
     * claim or a move to the person it is already on, (400) for a correction (it must stay with
     * the claim it corrects), (423) when dated inside a closed period and (422) when dated after
     * the new person's retirement date.
     */
    @Transactional
    public Claim reassign(String sheetId, String user, long id, long toPersonId) {
        if (!isSteward(sheetId, user)) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can move a claim.");
        }
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Claim claim = claims.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be moved.");
        }
        Person from = person(sheetId, claim.getPersonId());
        Person to = person(sheetId, toPersonId);
        if (from.getId().equals(to.getId())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That claim is already on that person.");
        }
        if (claim.isCorrection()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A correction cannot be moved.");
        }
        periods.refuseIfClosed(sheetId, claim.getDate());
        refuseIfRetired(to, claim.getDate());
        claim.setPersonId(to.getId());
        claim.bind(false, null);
        claims.saveAndFlush(claim);
        claims.listFirst(claim.getId());
        Claim saved = claims.findByIdAndSheetId(id, sheetId).orElseThrow();
        audit.recordOnCommit(record("CLAIM_REASSIGNED", sheetId, user, to, saved)
                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
                + " from=" + from.getName() + " to=" + to.getName());
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /** What a bulk open did: how many claims were opened and how many refused, and the claims opened. */
    public record BulkOpened(int opened, int refused, List<Claim> claims) {
    }

    /**
     * Open the given claims together, in list order (the order people were added, newest claim
     * first within a person), so they are numbered in that order. A claim that cannot be opened
     * (not on the sheet, not DRAFT, or dated inside a closed period) is refused and left as it is.
     */
    @Transactional
    public BulkOpened bulkOpen(String sheetId, String user, Collection<Long> ids) {
        List<Claim> selected = inListOrder(sheetId, ids);
        int refused = (int) ids.stream().distinct().count() - selected.size();
        List<Claim> opened = new ArrayList<>();
        for (Claim claim : selected) {
            if (claim.getStatus() != ClaimStatus.DRAFT || periods.isClosed(sheetId, claim.getDate())) {
                refused++;
                continue;
            }
            opened.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.OPEN));
        }
        return new BulkOpened(opened.size(), refused, opened);
    }

    /** What a bulk settle did: how many claims were settled (or made PENDING) and how many refused, and the claims changed. */
    public record BulkSettled(int settled, int refused, List<Claim> claims) {
    }

    /**
     * Settle the given claims together, in list order (the order people were added, newest claim
     * first within a person), each by exactly the rules of settling one claim. A claim a clerk's
     * settle makes PENDING counts as settled; a claim that cannot be settled is refused and left
     * as it is.
     */
    @Transactional
    public BulkSettled bulkSettle(String sheetId, String user, Collection<Long> ids) {
        List<Claim> selected = inListOrder(sheetId, ids);
        int refused = (int) ids.stream().distinct().count() - selected.size();
        List<Claim> settled = new ArrayList<>();
        for (Claim claim : selected) {
            try {
                settled.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.SETTLED));
            } catch (ResponseStatusException refusedOne) {
                // every refusal is checked before the claim is changed, so it is left as it is
                refused++;
            }
        }
        return new BulkSettled(settled.size(), refused, settled);
    }

    /** The given claims on the sheet in list order: people as added, newest claim first within a person. */
    private List<Claim> inListOrder(String sheetId, Collection<Long> ids) {
        Map<Long, Integer> personOrder = new HashMap<>();
        List<Person> listed = people.findBySheetIdOrderByIdAsc(sheetId);
        for (int i = 0; i < listed.size(); i++) {
            personOrder.put(listed.get(i).getId(), i);
        }
        return ids.stream().distinct()
                .flatMap(id -> claims.findByIdAndSheetId(id, sheetId).stream())
                .sorted(Comparator.<Claim>comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
                        .thenComparing(Claim::getListed, Comparator.reverseOrder()))
                .toList();
    }

