276	 * a statement bound it to, and is listed as its new person's newest claim. A steward can re-settle
277	 * a SETTLED claim: its due is fixed again at the figure it would have today as an open claim bound
278	 * by no statement (today's rates, grades, floor and late charge). An OPEN claim can be deferred to
279	 * a date after the sheet's today: until the sheet's today reaches it the claim counts in no total,
280	 * is not overdue, cannot be settled and is left unbound by a statement; from then on it is an OPEN
281	 * claim like any other.
282	 */
283	@Service
284	public class ClaimService {
285	
286	    private final ClaimRepository claims;
287	    private final PersonRepository people;
288	    private final RateRepository rates;
289	    private final SheetService sheets;
290	    private final Audit audit;
291	    private final RollupService rollup;
292	    private final PeriodService periods;
293	    private final RoleService roles;
294	
295	    public ClaimService(ClaimRepository claims, PersonRepository people, RateRepository rates, SheetService sheets,
296	            Audit audit, RollupService rollup, PeriodService periods, RoleService roles) {
297	        this.roles = roles;
298	        this.rollup = rollup;
299	        this.periods = periods;
300	        this.claims = claims;
301	        this.people = people;
302	        this.rates = rates;
303	        this.sheets = sheets;
304	        this.audit = audit;
305	    }
306	
307	    /**
308	     * A claim's figure under any late charge: the due fixed when settled, else the one bound by a
309	     * statement (not while PENDING), else the live due; null when it has none.
310	     */
311	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
312	        if (claim.getStatus() == ClaimStatus.SETTLED) {
313	            return claim.getSettledDue();
314	        }
315	        return claim.isStated() && claim.getStatus() != ClaimStatus.PENDING ? claim.getStatedDue()
316	                : due(sheetId, person, claim);
317	    }
318	
319	    /** A claim's figure with its late charge on the sheet's today added on top; null when it has none. */
320	    public BigDecimal charged(String sheetId, Person person, Claim claim) {
321	        return LateCharge.withCharge(sheets.sheet(sheetId), claim, figure(sheetId, person, claim));
322	    }
323	
324	    @Transactional(readOnly = true)
325	    public List<Claim> list(String sheetId) {
326	        return claims.findBySheetIdOrderByListedDesc(sheetId);
327	    }
328	
329	    @Transactional
330	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
331	            String corrects) {
332	        Person person = person(sheetId, personId);
333	        LocalDate dated = dateOrToday(sheetId, date);
334	        periods.refuseIfClosed(sheetId, dated);
335	        refuseIfRetired(person, dated);
336	        String corrected = corrected(sheetId, personId, amount, corrects);
337	        RollupService.Snapshot before = rollup.snapshot(sheetId);
338	        Claim claim = new Claim(sheetId, personId, amount, dated,
339	                dated.plusDays(sheets.sheet(sheetId).termsFor(person.gradeOn(dated), dated)), note, corrected);
340	        logStatus(sheetId, user, person, claim);
341	        Claim added = claims.saveAndFlush(claim);
342	        audit.recordOnCommit(record("CLAIM_ADDED", sheetId, user, person, added));
343	        rollup.recordChanges(sheetId, user, before);
344	        return added;
345	    }
346	
347	    @Transactional
348	    public Claim update(String sheetId, String user, long id, BigDecimal amount, LocalDate date, String note,
349	            String corrects) {
350	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
351	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
352	        if (claim.getStatus() != ClaimStatus.DRAFT) {
353	            throw new ResponseStatusException(HttpStatus.CONFLICT,
354	                    "A " + claim.getStatus() + " claim cannot be edited.");
355	        }
356	        LocalDate dated = dateOrToday(sheetId, date);
357	        periods.refuseIfClosed(sheetId, claim.getDate());
358	        periods.refuseIfClosed(sheetId, dated);
359	        refuseIfRetired(person(sheetId, claim.getPersonId()), dated);
360	        String corrected = corrected(sheetId, claim.getPersonId(), amount, corrects);
361	        RollupService.Snapshot before = rollup.snapshot(sheetId);
362	        claim.setAmount(amount);
363	        claim.setDate(dated);
364	        claim.setNote(note);
365	        claim.setCorrects(corrected);
366	        Claim saved = claims.saveAndFlush(claim);
367	        audit.recordOnCommit(record("CLAIM_EDITED", sheetId, user, person(sheetId, saved.getPersonId()), saved));
368	        rollup.recordChanges(sheetId, user, before);
369	        return saved;
370	    }
371	
372	    /**
373	     * Move a claim to a new status, refused (409) when its current status does not allow it, and
374	     * refused (403) when the user who opened it tries to settle it. A clerk settling one whose
375	     * figure is above the sheet's clerk limit makes it PENDING instead.
376	     */
377	    @Transactional
378	    public Claim changeStatus(String sheetId, String user, long id, ClaimStatus next) {
379	        return changeStatus(sheetId, user, id, next, null, false);
380	    }
381	
382	    /**
383	     * Approve a PENDING claim: it becomes SETTLED, its due fixed at its live figure with its late
384	     * charge on the sheet's today. Refused (409) when not PENDING, and (403) for a clerk or the
385	     * user who opened it.
386	     */
387	    @Transactional
388	    public Claim approve(String sheetId, String user, long id) {
389	        return changeStatus(sheetId, user, id, ClaimStatus.SETTLED, null, true);
390	    }
391	
392	    /**
393	     * Reject a PENDING claim with a reason: it is OPEN again, bound again by the last statement if
394	     * that statement included it. Refused (409) when not PENDING, and (403) for a clerk.
395	     */
396	    @Transactional
397	    public Claim reject(String sheetId, String user, long id, String reason) {
398	        return changeStatus(sheetId, user, id, ClaimStatus.OPEN, reason, true);
399	    }
400	
401	    /** Move a claim to a new status; {@code review} for a steward's approval or rejection of a PENDING claim. */
402	    private Claim changeStatus(String sheetId, String user, long id, ClaimStatus next, String reason,
403	            boolean review) {
404	        // lock the sheet's numbering before reading the claim, so a claim is opened (and numbered) once
405	        if (next == ClaimStatus.OPEN) {
406	            sheets.lock(sheetId);
407	        }
408	        RollupService.Snapshot before = rollup.snapshot(sheetId);
409	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
410	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
411	        ClaimStatus was = claim.getStatus();
412	        // only a steward's review moves a PENDING claim on, other than voiding it
413	        if (!was.canBecome(next) || (next != ClaimStatus.VOID && review != (was == ClaimStatus.PENDING))) {
414	            throw new ResponseStatusException(HttpStatus.CONFLICT,
415	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
416	        }
417	        periods.refuseIfClosed(sheetId, claim.getDate());
418	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
419	            throw new ResponseStatusException(HttpStatus.CONFLICT,
420	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then.");
421	        }
422	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
423	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
424	                    "The user who opened a claim cannot " + (review ? "approve" : "settle") + " it.");
425	        }
426	        if (review && !isSteward(sheetId, user)) {
427	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
428	                    "Only a steward can approve or reject a PENDING claim.");
429	        }
430	        Person person = person(sheetId, claim.getPersonId());
431	        // settling fixes the figure with its late charge as it stands on the sheet's today (a
432	        // PENDING claim's figure is live)
433	        BigDecimal settling = next == ClaimStatus.SETTLED ? charged(sheetId, person, claim) : null;
434	        if (next == ClaimStatus.SETTLED && !review && aboveClerkLimit(sheetId, user, settling)) {
435	            next = ClaimStatus.PENDING;
436	            settling = null;
437	        }
438	        claim.setStatus(next);
439	        if (next == ClaimStatus.OPEN && !review) {
440	            claim.setNumber(sheets.nextClaimNumber(sheetId, claim.getDate()));
441	            claim.setOpenedBy(user);
442	        } else if (next == ClaimStatus.SETTLED) {
443	            claim.setSettledDue(settling);
444	        }
445	        logStatus(sheetId, user, person, claim);
446	        Claim saved = claims.saveAndFlush(claim);
447	        String event = switch (next) {
448	            case OPEN -> review ? "CLAIM_REJECTED" : "CLAIM_OPENED";
449	            case PENDING -> "CLAIM_PENDING";
450	            case SETTLED -> review ? "CLAIM_APPROVED" : "CLAIM_SETTLED";
451	            case VOID -> "CLAIM_VOIDED";
452	            case DRAFT -> throw new IllegalStateException();
453	        };
454	        audit.recordOnCommit(record(event, sheetId, user, person, saved)
455	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
456	                + (next == ClaimStatus.SETTLED ? " due=" + dueText(saved.getSettledDue()) : "")
457	                + (reason != null ? " reason=" + reason : ""));
458	        rollup.recordChanges(sheetId, user, before);
459	        return saved;
460	    }
461	
462	    /**
463	     * Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it
464	     * the claim counts in no total, is not overdue, cannot be settled and is left unbound by a
465	     * statement (deferring unbinds it). Refused (409) for a claim that is not OPEN, (400) for a date
466	     * not after the sheet's today and (423) when dated inside a closed period.
467	     */
468	    @Transactional
469	    public Claim defer(String sheetId, String user, long id, LocalDate until) {
470	        RollupService.Snapshot before = rollup.snapshot(sheetId);
471	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
472	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
473	        if (claim.getStatus() != ClaimStatus.OPEN) {
474	            throw new ResponseStatusException(HttpStatus.CONFLICT,
475	                    "A " + claim.getStatus() + " claim cannot be deferred.");
476	        }
477	        if (!until.isAfter(sheets.today(sheetId))) {
478	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
479	                    "A claim can only be deferred to a date after the sheet's today.");
480	        }
481	        periods.refuseIfClosed(sheetId, claim.getDate());
482	        Person person = person(sheetId, claim.getPersonId());
483	        claim.setDeferredUntil(until);
484	        claim.bind(false, null);
485	        Claim saved = claims.saveAndFlush(claim);
486	        audit.recordOnCommit(record("CLAIM_DEFERRED", sheetId, user, person, saved)
487	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "") + " until=" + until);
488	        rollup.recordChanges(sheetId, user, before);
489	        return saved;
490	    }
491	
492	    /**
493	     * Re-settle a SETTLED claim: fix its due again at the figure it would have on the sheet's today
494	     * as an open claim bound by no statement, with its late charge. Refused (403) for anyone but a
495	     * steward, (409) for a claim that is not SETTLED and (423) when dated inside a closed period.
496	     */
497	    @Transactional
498	    public Claim resettle(String sheetId, String user, long id) {
499	        if (!isSteward(sheetId, user)) {
500	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can re-settle a claim.");
501	        }
502	        RollupService.Snapshot before = rollup.snapshot(sheetId);
503	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
504	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
505	        if (claim.getStatus() != ClaimStatus.SETTLED) {
506	            throw new ResponseStatusException(HttpStatus.CONFLICT,
507	                    "A " + claim.getStatus() + " claim cannot be re-settled.");
508	        }
509	        periods.refuseIfClosed(sheetId, claim.getDate());
510	        Person person = person(sheetId, claim.getPersonId());
511	        BigDecimal old = claim.getSettledDue();
512	        BigDecimal settling = LateCharge.withChargeAsOpen(sheets.sheet(sheetId), claim, due(sheetId, person, claim));
513	        claim.setSettledDue(settling);
514	        logStatus(sheetId, user, person, claim);
515	        Claim saved = claims.saveAndFlush(claim);
516	        audit.recordOnCommit(record("CLAIM_RESETTLED", sheetId, user, person, saved)
517	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
518	                + " old=" + dueText(old) + " new=" + dueText(settling));
519	        rollup.recordChanges(sheetId, user, before);
520	        return saved;
521	    }
522	
523	    /**
524	     * Move a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its number and
525	     * date, is unbound from any statement (live again until its new person's next statement), and
526	     * is listed first under its new person. Refused (403) for a clerk, (409) for a SETTLED or VOID
527	     * claim or a move to the person it is already on, (400) for a correction (it must stay with
528	     * the claim it corrects), (423) when dated inside a closed period and (422) when dated after
529	     * the new person's retirement date.
530	     */
531	    @Transactional
532	    public Claim reassign(String sheetId, String user, long id, long toPersonId) {
533	        if (!isSteward(sheetId, user)) {
534	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can move a claim.");
535	        }
536	        RollupService.Snapshot before = rollup.snapshot(sheetId);
537	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
538	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
539	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
540	            throw new ResponseStatusException(HttpStatus.CONFLICT,
541	                    "A " + claim.getStatus() + " claim cannot be moved.");
542	        }
543	        Person from = person(sheetId, claim.getPersonId());
544	        Person to = person(sheetId, toPersonId);
545	        if (from.getId().equals(to.getId())) {
546	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That claim is already on that person.");
547	        }
548	        if (claim.isCorrection()) {
549	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A correction cannot be moved.");
550	        }
551	        periods.refuseIfClosed(sheetId, claim.getDate());
552	        refuseIfRetired(to, claim.getDate());
553	        claim.setPersonId(to.getId());
554	        claim.bind(false, null);
555	        claims.saveAndFlush(claim);
556	        claims.listFirst(claim.getId());
557	        Claim saved = claims.findByIdAndSheetId(id, sheetId).orElseThrow();
558	        audit.recordOnCommit(record("CLAIM_REASSIGNED", sheetId, user, to, saved)
559	                + (saved.getNumber() != null ? " number=" + saved.getNumber() : "")
560	                + " from=" + from.getName() + " to=" + to.getName());
561	        rollup.recordChanges(sheetId, user, before);
562	        return saved;
563	    }
564	
565	    /** What a bulk open did: how many claims were opened and how many refused, and the claims opened. */
566	    public record BulkOpened(int opened, int refused, List<Claim> claims) {
567	    }
568	
569	    /**
570	     * Open the given claims together, in list order (the order people were added, newest claim
571	     * first within a person), so they are numbered in that order. A claim that cannot be opened
572	     * (not on the sheet, not DRAFT, or dated inside a closed period) is refused and left as it is.
573	     */
574	    @Transactional
575	    public BulkOpened bulkOpen(String sheetId, String user, Collection<Long> ids) {
576	        List<Claim> selected = inListOrder(sheetId, ids);
577	        int refused = (int) ids.stream().distinct().count() - selected.size();
578	        List<Claim> opened = new ArrayList<>();
579	        for (Claim claim : selected) {
580	            if (claim.getStatus() != ClaimStatus.DRAFT || periods.isClosed(sheetId, claim.getDate())) {
581	                refused++;
582	                continue;
583	            }
584	            opened.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.OPEN));
585	        }
586	        return new BulkOpened(opened.size(), refused, opened);
587	    }
588	
589	    /** What a bulk settle did: how many claims were settled (or made PENDING) and how many refused, and the claims changed. */
590	    public record BulkSettled(int settled, int refused, List<Claim> claims) {
591	    }
592	
593	    /**
594	     * Settle the given claims together, in list order (the order people were added, newest claim
595	     * first within a person), each by exactly the rules of settling one claim. A claim a clerk's
596	     * settle makes PENDING counts as settled; a claim that cannot be settled is refused and left
597	     * as it is.
598	     */
599	    @Transactional
600	    public BulkSettled bulkSettle(String sheetId, String user, Collection<Long> ids) {
601	        List<Claim> selected = inListOrder(sheetId, ids);
602	        int refused = (int) ids.stream().distinct().count() - selected.size();
603	        List<Claim> settled = new ArrayList<>();
604	        for (Claim claim : selected) {
605	            try {
606	                settled.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.SETTLED));
607	            } catch (ResponseStatusException refusedOne) {
608	                // every refusal is checked before the claim is changed, so it is left as it is
609	                refused++;
610	            }
611	        }
612	        return new BulkSettled(settled.size(), refused, settled);
613	    }
614	
615	    /** The given claims on the sheet in list order: people as added, newest claim first within a person. */
616	    private List<Claim> inListOrder(String sheetId, Collection<Long> ids) {
617	        Map<Long, Integer> personOrder = new HashMap<>();
618	        List<Person> listed = people.findBySheetIdOrderByIdAsc(sheetId);
619	        for (int i = 0; i < listed.size(); i++) {
620	            personOrder.put(listed.get(i).getId(), i);
621	        }
622	        return ids.stream().distinct()
623	                .flatMap(id -> claims.findByIdAndSheetId(id, sheetId).stream())
624	                .sorted(Comparator.<Claim>comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
625	                        .thenComparing(Claim::getListed, Comparator.reverseOrder()))
626	                .toList();
627	    }
628	
629	    /**
630	     * The due on a claim's amount at the rate for the person's grade in force on the claim's date,
631	     * rounded to the cent as the claim rounds (see {@link Rounding}) and raised to the floor in force on the claim's date (a correction's is not); null with no
632	     * rate in force then.
633	     */
634	    public BigDecimal due(String sheetId, Person person, Claim claim) {
635	        Sheet sheet = sheets.sheet(sheetId);
636	        RoundingMode rounding = Rounding.mode(sheet, roundingDate(sheetId, claim));
637	        return rates.findInForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate()).map(Rate::getPct)
638	                .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, rounding))
639	                .map(due -> claim.isCorrection() ? due : due.max(sheet.floorOn(claim.getDate())))
640	                .orElse(null);
641	    }
642	
643	    /** The date a claim rounds by: its own, or for a correction that of the claim it corrects. */
644	    private LocalDate roundingDate(String sheetId, Claim claim) {
645	        if (!claim.isCorrection() || claim.getCorrects() == null) {
646	            return claim.getDate();
647	        }
648	        return Rounding.dateOf(claim, claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId()));
649	    }
650	
651	    /** Log the claim's status as it is now: by the user, on the sheet's today, with its due as computed now. */
652	    private void logStatus(String sheetId, String user, Person person, Claim claim) {
653	        claim.log(new ClaimLogEntry(claim.getStatus(), user, sheets.today(sheetId),
654	                dueText(charged(sheetId, person, claim))));
655	    }
656	
657	    private static String dueText(BigDecimal due) {
658	        return due == null ? "n/a" : due.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
659	    }
660	
661	    /** Whether the user is a clerk settling a claim whose figure is above the sheet's clerk limit. */
662	    private boolean aboveClerkLimit(String sheetId, String user, BigDecimal figure) {
663	        BigDecimal limit = sheets.clerkLimit(sheetId);
664	        return figure != null && limit != null && figure.compareTo(limit) > 0 && !isSteward(sheetId, user);
665	    }
666	
667	    private boolean isSteward(String sheetId, String user) {
668	        return Role.STEWARD.equals(roles.roleOf(sheetId, user));
669	    }
670	
671	    /**
672	     * The number a claim corrects: none unless its amount is negative, when it must name the number
673	     * of a SETTLED claim of the same person, else it is refused (400).
674	     */
675	    private String corrected(String sheetId, long personId, BigDecimal amount, String corrects) {
676	        if (amount.signum() >= 0) {
677	            return null;
678	        }
679	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId).stream()
680	                .anyMatch(c -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED);
681	        if (!settled) {
682	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
683	                    "A negative amount must correct a SETTLED claim of the same person, by its number.");
684	        }
685	        return corrects;
686	    }
687	
688	    /** Refuse (422) a claim dated after its person's retirement date. */
689	    private static void refuseIfRetired(Person person, LocalDate date) {
690	        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
691	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
692	                    "That claim's date is after its person's retirement date.");
693	        }
694	    }
695	
696	    private Person person(String sheetId, long personId) {
697	        return people.findByIdAndSheetId(personId, sheetId)
698	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
699	    }
700	
701	    private static String record(String event, String sheetId, String user, Person person, Claim claim) {
702	        return event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName() + " amount="
703	                + claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString() + " date=" + claim.getDate();
704	    }
705	
706	    private LocalDate dateOrToday(String sheetId, LocalDate date) {
707	        return date != null ? date : sheets.today(sheetId);
708	    }
709	}
